#!/usr/bin/env node
import { readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { join, dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = dirname(fileURLToPath(import.meta.url))
const ROOT = resolve(__dirname, '..')
const MIGRATIONS_DIR = join(ROOT, 'drizzle')
const OUTPUT = join(ROOT, 'src/runtime/server/database/migrations.ts')

const journalPath = join(MIGRATIONS_DIR, 'meta/_journal.json')
const journal = JSON.parse(readFileSync(journalPath, 'utf-8'))

const entries = journal.entries.map((entry) => {
  const sqlPath = join(MIGRATIONS_DIR, `${entry.tag}.sql`)
  const sql = readFileSync(sqlPath, 'utf-8')
  return { tag: entry.tag, when: entry.when, sql }
})

const body = `// AUTO-GENERATED by scripts/bundle-migrations.js — do not edit by hand.
// Run \`pnpm db:generate\` to regenerate after schema changes.

export interface BundledMigration {
  tag: string
  when: number
  sql: string
}

export const MIGRATIONS: BundledMigration[] = ${JSON.stringify(entries, null, 2)}
`

writeFileSync(OUTPUT, body)
console.log(`[bundle-migrations] wrote ${entries.length} migration(s) → ${OUTPUT.replace(ROOT + '/', '')}`)
